      const heads = `M${n2(x1)} ${y}l5 -2.5v5zM${n2(x2)} ${y}l-5 -2.5v5z`;
      return K.path(d, 'fa') + `<path d="${heads}"${paint('fa', 'fa')}/>` + K.t(m, y + 3.5, label, c, 'middle');
